386	/// Rewrite the whole todo projection: the `todos.md` index, one
387	/// `todos/<id>.md` per todo, and a sweep that deletes the per-todo files of
388	/// todos that no longer exist.
389	pub(crate) fn project_todos(ws: &Path, todos: &[Todo]) -> io::Result<()> {
390	    fs::create_dir_all(todos_dir(ws))?;
391	    atomic_write(&todos_index_path(ws), &render_todos_index_md(todos))?;
392	    for todo in todos {
393	        atomic_write(&todo_path(ws, todo.id), &render_todo_md(todo))?;
394	    }
395	
396	    // Remove the per-todo file of any todo that has since been deleted.
397	    let live: HashSet<u64> = todos.iter().map(|t| t.id).collect();
398	    if let Ok(entries) = fs::read_dir(todos_dir(ws)) {
399	        for entry in entries.flatten() {
400	            let name = entry.file_name();
401	            let stem = match name.to_string_lossy().strip_suffix(".md") {
402	                Some(stem) => stem.to_string(),
403	                None => continue,
404	            };
405	            if let Ok(id) = stem.parse::<u64>() {
406	                if !live.contains(&id) {
407	                    let _ = fs::remove_file(entry.path());
408	                }
409	            }
410	        }
411	    }
412	    Ok(())
413	}
