420	/// Rewrite `.panopt/notes.md` from the project's
421	/// `(id, title, updated_at)` list, and sweep per-note files whose
422	/// note has been deleted. Mirrors the sweep in [`project_todos`] so the
423	/// index is the source of truth for which files should exist.
424	pub(crate) fn project_notes_index(ws: &Path, pads: &[(u64, String, String)]) -> io::Result<()> {
425	    atomic_write(&notes_index_path(ws), &render_notes_index_md(pads))?;
426	
427	    let live: HashSet<u64> = pads.iter().map(|(id, _, _)| *id).collect();
