    panopt_dir(ws).join("roster.md")
}

fn agents_path(ws: &Path) -> PathBuf {
    panopt_dir(ws).join("agents.md")
}

fn locks_path(ws: &Path) -> PathBuf {
    panopt_dir(ws).join("locks.md")
}

