#[test]
fn agent_rows_carry_type_state_and_registry_idle() {
    let now = SystemTime::UNIX_EPOCH + Duration::from_secs(600);
    let processes = vec![
        Process {
            id: 1,
            kind: ProcessKind::Agent,
            name: "claude-a".into(),
            display_name: "Mediator".into(),
            agent_tool_id: Some(7),
            status: Some("running".into()),
            agent_state: Some("thinking".into()),
            ..Default::default()
        },
        // A command row gets none of the agent-only segments even with a
        // matching tool-type entry.
        Process {
            id: 2,
            kind: ProcessKind::Command,
            name: "Build".into(),
            ..Default::default()
        },
    ];
    let tool_types = std::collections::BTreeMap::from([(7u64, "claude-code".to_string())]);
    // Registry entry keyed by the agent id (the row's `name`), last seen
    // 60s ago -> `idle:1m`.
    let agents = vec![Agent {
        name: "claude-a".into(),
        status: String::new(),
        last_seen: SystemTime::UNIX_EPOCH + Duration::from_secs(540),
        ..Default::default()
    }];
    assert_eq!(
        render_processes_md(&processes, &tool_types, &agents, now),
        "# Processes\n\n\
         - [agent] #1 Mediator (from #7) · running · type:claude-code · state:thinking · idle:1m\n\
         - [command] #2 Build\n"
    );
}

